          <label class="switch" title="浮盈達啟動%後，價格回到成本保本線時直接保護出場，不再等待放量/結構確認"><input id="simBreakEvenEnabled" type="checkbox" checked><span class="slider"></span><span>成本保本</span></label><label>保本啟動 % <input id="simBreakEvenTriggerPct" type="number" min="0" step="0.1" value="1"></label>
          <label title="ATR=真實波幅；固定/ATR取大=兩者取較寬；標準差σ=來源週期報酬波動；反彈分位=近期不利振幅分位">移動模式 <select id="simTrailMode"><option value="FIXED">固定%</option><option value="ATR">ATR動態</option><option value="MAX_FIXED_ATR">固定/ATR取大</option><option value="SIGMA">標準差σ</option><option value="REBOUND_QUANTILE">反彈分位</option></select></label>
          <label>動態來源週期 <select id="simSourceIntervalSeconds"><option value="1">1秒</option><option value="5">5秒</option><option value="15">15秒</option><option value="30">30秒</option><option value="60">60秒</option></select></label>
          <label>回看K <input id="simLookback" type="number" min="2" max="500" value="20"></label><label>倍數 <input id="simMultiplier" type="number" min="0" step="0.1" value="1.5"></label><label>分位% <input id="simQuantile" type="number" min="0" max="100" step="1" value="80"></label>
          <label title="只限制移動出場；固定停損不等待確認">移動確認 <select id="simConfirmation"><option value="NONE">不確認</option><option value="VOLUME">放量</option><option value="STRUCTURE">結構突破</option><option value="VOLUME_OR_STRUCTURE">放量或結構</option></select></label><label title="確認K收盤=舊版；確認觸發價=若結構確認成立，使用移動門檻與結構線同時成立的第一個價位；純放量確認因無法還原K內時序，仍使用確認K收盤">確認成交 <select id="simConfirmationFillMode"><option value="BAR_CLOSE">確認K收盤</option><option value="CONFIRM_TOUCH">確認觸發價（實驗）</option></select></label><label>量倍 <input id="simVolumeMultiplier" type="number" min="0" step="0.1" value="1.5"></label>
