  <section class="panel table-panel auto-table"><div style="padding:7px 9px 0"><span class="section-no">7</span><span style="color:var(--muted)">自動策略交易清單（僅分析）</span></div><div class="scroll"><table><thead><tr><th>策略</th><th>方向</th><th>進場時間</th><th>進場價</th><th>出場時間</th><th>出場價</th><th>出場原因</th><th>淨損益</th><th>實際報酬率</th></tr></thead><tbody id="autoTrades"><tr><td colspan="9" class="empty">策略 A / B 預設關閉</td></tr></tbody></table></div></section>
